/// 真机端到端：下载（真实 HTTP）+ audiotags 原生写标签（标题/歌手/专辑/歌词/封面）
import 'dart:convert';
import 'dart:io';
import 'package:audiotags/audiotags.dart';
import 'package:core/core.dart';
import 'package:db/db.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:integration_test/integration_test.dart';
import 'package:path_provider/path_provider.dart';

const String _mp3B64 = '';
const String _jpgB64 = '';

Future<DownloadTask?> _wait(DownloadManager dm, String key) async {
  for (var i = 0; i < 100; i++) {
    await Future.delayed(const Duration(milliseconds: 100));
    final t = dm.getTasks().where((x) => x.songKey == key).firstOrNull;
    if (t == null) continue;
    if (t.status == DownloadStatus.completed ||
        t.status == DownloadStatus.failed) return t;
  }
  return null;
}

void main() {
  IntegrationTestWidgetsFlutterBinding.ensureInitialized();

  testWidgets('下载并写入真实标签（Android 原生 audiotags）', (tester) async {
    initSqfliteForPlatform();
    final base = await getTemporaryDirectory();
    final ts = DateTime.now().microsecondsSinceEpoch;
    final dbDir = Directory('${base.path}/e2e_db_$ts')..createSync(recursive: true);
    final dlDir = Directory('${base.path}/e2e_dl_$ts')..createSync(recursive: true);
    final provider = SqfliteDatabaseProvider.withHelper(
        DatabaseHelper(customDbPath: '${dbDir.path}/e2e.db'));
    await provider.initialize();

    final cover = base64Decode(_jpgB64);
    final audio = base64Decode(_mp3B64);
    final server = await HttpServer.bind(InternetAddress.loopbackIPv4, 0);
    server.listen((req) {
      if (req.uri.path == '/cover.jpg') {
        req.response
          ..statusCode = 200
          ..headers.contentType = ContentType('image', 'jpeg')
          ..contentLength = cover.length
          ..add(cover)
          ..close();
      } else {
        req.response
          ..statusCode = 200
          ..headers.contentType = ContentType('audio', 'mpeg')
          ..contentLength = audio.length
          ..add(audio)
          ..close();
      }
    });

    final dm = DownloadManagerImpl(
      songDao: provider.songDao,
      downloadTaskDao: provider.downloadTaskDao,
      settingsDao: provider.settingsDao,
      customCacheDir: dlDir.path,
    );
    await dm.init();
    final song = Song(
      id: 'e2e1',
      sourceId: 'local',
      title: '真机歌',
      artist: '歌手',
      album: '专辑',
      coverUrl: 'http://127.0.0.1:${server.port}/cover.jpg',
      playUrl: 'http://127.0.0.1:${server.port}/a.mp3',
    );
    await dm.download(song, lyrics: '[00:01.00]真机歌词');
    final task = await _wait(dm, song.globalKey);
    expect(task, isNotNull);
    expect(task!.status, DownloadStatus.completed, reason: '下载失败: ${task.error}');
    expect(task.warning, isNull, reason: '元信息 warning: ${task.warning}');

    final tag = await AudioTags.read(task.localPath!);
    expect(tag, isNotNull);
    expect(tag!.title, '真机歌');
    expect(tag.trackArtist, '歌手');
    expect(tag.album, '专辑');
    expect(tag.lyrics, contains('真机歌词'));
    expect(tag.pictures, isNotEmpty, reason: '封面应写入');
    final f = File(task.localPath!);
    expect(f.existsSync(), isTrue);

    await server.close();
    dm.dispose();
    await provider.close();
    dbDir.deleteSync(recursive: true);
    dlDir.deleteSync(recursive: true);
  });
}
